={
  "model": "llama-3.3-70b-versatile",
  "response_format": { "type": "json_object" },
  "messages": [
    {
      "role": "system",
      "content": "You are a language and intent analyzer. Analyze the user's message and return JSON.\n\nDetect:\n1. Language: en (English), ta (Tamil), hi (Hindi), te (Telugu), kn (Kannada), ml (Malayalam)\n2. Intent: greeting, compare, claim, policy_info, general\n3. Entities: Extract policy types, coverage amounts, family details if mentioned\n\nReturn ONLY this JSON structure:\n{\n  \"detected_language\": \"en\",\n  \"intent\": \"general\",\n  \"entities\": {},\n  \"original_text\": \"user message here\"\n}"
    },
    {
      "role": "user",
      "content": "{{ $json.body?.query ?? $json.query ?? '' }}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 200
}

parameters.jsCode:
// Parse the detection result
const detectionResult = JSON.parse($json.choices[0].message.content);
const originalQuery = $('Main Webhook').first().json.body?.query ?? $('Main Webhook').first().json.query ?? '';
const action = $('Main Webhook').first().json.body?.action ?? $('Main Webhook').first().json.action ?? 'voice';
const policies = $('Main Webhook').first().json.body?.policies ?? $('Main Webhook').first().json.policies ?? [];
const hasPolicies = Array.isArray(policies) && policies.length > 0;

return {
  json: {
    detected_language: detectionResult.detected_language || 'en',
    intent: detectionResult.intent || 'general',
    entities: detectionResult.entities || {},
    original_query: originalQuery,
    action: action,
    has_policies: hasPolicies
  }
};

// Generate a friendly greeting in the detected language
const lang = $json.detected_language || 'en';
const greetings = {
  'en': 'Hello! I\'m your insurance assistant. How can I help you today? You can ask me about health insurance, compare policies, or get help with claims.',
  'hi': 'नमस्ते! मैं आपका बीमा सहायक हूं। मैं आज आपकी कैसे मदद कर सकता हूं? आप मुझसे स्वास्थ्य बीमा के बारे में पूछ सकते हैं, पॉलिसियों की तुलना कर सकते हैं, या दावों में मदद ले सकते हैं।',
  'ta': 'வணக்கம்! நான் உங்கள் காப்பீட்டு உதவியாளர். இன்று நான் உங்களுக்கு எப்படி உதவ முடியும்? சுகாதார காப்பீடு பற்றி கேளுங்கள், பாலிசிகளை ஒப்பிடுங்கள்.',
  'te': 'నమస్కారం! నేను మీ బీమా సహాయకుడిని. ఈ రోజు నేను మీకు ఎలా సహాయం చేయగలను?',
  'kn': 'ನಮಸ್ಕಾರ! ನಾನು ನಿಮ್ಮ ವಿಮಾ ಸಹಾಯಕ. ಇಂದು ನಾನು ನಿಮಗೆ ಹೇಗೆ ಸಹಾಯ ಮಾಡಬಹುದು?',
  'ml': 'നമസ്കാരം! ഞാൻ നിങ്ങളുടെ ഇൻഷുറൻസ് അസിസ്റ്റന്റാണ്. ഇന്ന് എനിക്ക് നിങ്ങളെ എങ്ങനെ സഹായിക്കാനാകും?'
};

return {
  json: {
    response: greetings[lang] || greetings['en'],
    detected_language: lang,
    intent: 'greeting'
  }
};
